import{_ as t,a0 as l,w as r,s as o,ao as d,I as p,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"從 Linux 命令列進行打印 | LCTT x X-CMD","titleTemplate":false,"description":"從 Linux 命令列進行打印 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"從 Linux 命令列進行打印 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"從 Linux 命令列進行打印 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190322 Printing from the Linux command line","title":"從 Linux 命令列進行打印","tag":"202101","desc":""},"relativePath":"202101/20190322 Printing from the Linux command line.md","filePath":"[post].md"}'),c={name:"202101/20190322 Printing from the Linux command line.md"};function h(g,s,k,u,b,m){const a=l("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="從-linux-命令列進行打印" tabindex="-1">從 Linux 命令列進行打印 <a class="header-anchor" href="#從-linux-命令列進行打印" aria-label="Permalink to “從 Linux 命令列進行打印”">​</a></h1><blockquote><p>在 Linux 命令列進行打印的內容比單單一個 <code>lp</code> 命令多得多，讓我們來看一些可用選項。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/03/printouts-paper-100791390-large.jpg" alt="Sherry CC BY 2.0"></p><p>Linux 命令列打印很容易。你可以使用 <code>lp</code> 命令來請求打印，並使用 <code>lpq</code> 命令來查看隊列中有哪些打印作業，但是當你要雙面打印或使用縱向模式時，這些會變得有些複雜。你可能還需要做很多其他事情，例如打印多份文檔副本或取消打印作業。讓我們來看看一些選項，當你從命令列打印時，如何讓你的打印輸出看起來如你所願。</p><h3 id="顯示打印機配置" tabindex="-1">顯示打印機配置 <a class="header-anchor" href="#顯示打印機配置" aria-label="Permalink to “顯示打印機配置”">​</a></h3><p>要從命令列查看打印機設置，請使用 <code>lpoptions</code> 命令。 輸出應如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions</span></span>
<span class="line"><span>copies=1 device-uri=dnssd://HP%20Color%20LaserJet%20CP2025dn%20(F47468)._pdl-datastream._tcp.local/ finishings=3 job-cancel-after=10800 job-hold-until=no-hold job-priority=50 job-sheets=none,none marker-change-time=1553023232 marker-colors=#000000,#00FFFF,#FF00FF,#FFFF00 marker-levels=18,62,62,63 marker-names=&#39;Black\\ Cartridge\\ HP\\ CC530A,Cyan\\ Cartridge\\ HP\\ CC531A,Magenta\\ Cartridge\\ HP\\ CC533A,Yellow\\ Cartridge\\ HP\\ CC532A&#39; marker-types=toner,toner,toner,toner number-up=1 printer-commands=none printer-info=&#39;HP Color LaserJet CP2025dn (F47468)&#39; printer-is-accepting-jobs=true printer-is-shared=true printer-is-temporary=false printer-location printer-make-and-model=&#39;HP Color LaserJet cp2025dn pcl3, hpcups 3.18.7&#39; printer-state=3 printer-state-change-time=1553023232 printer-state-reasons=none printer-type=167964 printer-uri-supported=ipp://localhost/printers/Color-LaserJet-CP2025dn sides=one-sided</span></span></code></pre></div><p>如果將其空格轉換為回車符，輸出可能會更人性化，請注意列出了多少設置選項。</p><p>注意：在下面的輸出中，一些行被重新鏈接，以使輸出更具可讀性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions | tr &quot; &quot; &#39;\\n&#39;</span></span>
<span class="line"><span>copies=1</span></span>
<span class="line"><span>device-uri=dnssd://HP%20Color%20LaserJet%20CP2025dn%20(F47468)._pdl-datastream._tcp.local/</span></span>
<span class="line"><span>finishings=3</span></span>
<span class="line"><span>job-cancel-after=10800</span></span>
<span class="line"><span>job-hold-until=no-hold</span></span>
<span class="line"><span>job-priority=50</span></span>
<span class="line"><span>job-sheets=none,none</span></span>
<span class="line"><span>marker-change-time=1553023232</span></span>
<span class="line"><span>marker-colors=#000000,#00FFFF,#FF00FF,#FFFF00</span></span>
<span class="line"><span>marker-levels=18,62,62,63</span></span>
<span class="line"><span>marker-names=&#39;Black\\ Cartridge\\ HP\\ CC530A,</span></span>
<span class="line"><span>Cyan\\ Cartridge\\ HP\\ CC531A,</span></span>
<span class="line"><span>Magenta\\ Cartridge\\ HP\\ CC533A,</span></span>
<span class="line"><span>Yellow\\ Cartridge\\ HP\\ CC532A&#39;</span></span>
<span class="line"><span>marker-types=toner,toner,toner,toner</span></span>
<span class="line"><span>number-up=1</span></span>
<span class="line"><span>printer-commands=none</span></span>
<span class="line"><span>printer-info=&#39;HP Color LaserJet CP2025dn (F47468)&#39;</span></span>
<span class="line"><span>printer-is-accepting-jobs=true</span></span>
<span class="line"><span>printer-is-shared=true</span></span>
<span class="line"><span>printer-is-temporary=false</span></span>
<span class="line"><span>printer-location</span></span>
<span class="line"><span>printer-make-and-model=&#39;HP Color LaserJet cp2025dn pcl3, hpcups 3.18.7&#39;</span></span>
<span class="line"><span>printer-state=3</span></span>
<span class="line"><span>printer-state-change-time=1553023232</span></span>
<span class="line"><span>printer-state-reasons=none</span></span>
<span class="line"><span>printer-type=167964</span></span>
<span class="line"><span>printer-uri-supported=ipp://localhost/printers/Color-LaserJet-CP2025dn</span></span>
<span class="line"><span>sides=one-sided</span></span></code></pre></div><p>使用 <code>-v</code> 選項時，<code>lpinfo</code> 命令將列出驅動程序和相關信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpinfo -v</span></span>
<span class="line"><span>network ipp</span></span>
<span class="line"><span>network https</span></span>
<span class="line"><span>network socket</span></span>
<span class="line"><span>network beh</span></span>
<span class="line"><span>direct hp</span></span>
<span class="line"><span>network lpd</span></span>
<span class="line"><span>file cups-brf:/</span></span>
<span class="line"><span>network ipps</span></span>
<span class="line"><span>network http</span></span>
<span class="line"><span>direct hpfax</span></span>
<span class="line"><span>network dnssd://HP%20Color%20LaserJet%20CP2025dn%20(F47468)._pdl-datastream._tcp.local/ &lt;== printer</span></span>
<span class="line"><span>network socket://192.168.0.23 &lt;== printer IP</span></span></code></pre></div><p><code>lpoptions</code> 命令將顯示默認打印機的設置。使用 <code>-p</code> 選項指定其中一個可用打印機代號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions -p LaserJet</span></span></code></pre></div><p><code>lpstat -p</code> 命令顯示打印機的狀態，而 <code>lpstat -p -d</code> 列出可用打印機列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpstat -p -d</span></span>
<span class="line"><span>printer Color-LaserJet-CP2025dn is idle. enabled since Tue 19 Mar 2019 05:07:45 PM EDT</span></span>
<span class="line"><span>system default destination: Color-LaserJet-CP2025dn</span></span></code></pre></div><h3 id="非常有用的命令" tabindex="-1">非常有用的命令 <a class="header-anchor" href="#非常有用的命令" aria-label="Permalink to “非常有用的命令”">​</a></h3><p>要在默認打印機上打印文檔，只需使用 <code>lp</code> 命令，後跟要打印的文件名即可。 如果文件名包含空格（在 Linux 系統上很少見），請將該名稱放在引號中或開始輸入文件名並按 <code>Tab</code> 鍵調用空格的轉義標誌（如下面的第二個示例所示）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp &quot;never leave home angry&quot;</span></span>
<span class="line"><span>$ lp never\\ leave\\ home\\ angry</span></span></code></pre></div><p><code>lpq</code> 命令顯示打印隊列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpq</span></span>
<span class="line"><span>Color-LaserJet-CP2025dn is ready and printing</span></span>
<span class="line"><span>Rank Owner Job File(s) Total Size</span></span>
<span class="line"><span>active shs 234 agenda 2048 bytes</span></span></code></pre></div><p>使用 <code>-n</code> 選項時，<code>lp</code> 命令可用來指定所需打印輸出的份數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp -n 11 agenda</span></span></code></pre></div><p>要取消打印作業，可以使用 <code>cancel</code> 或 <code>lprm</code> 命令。如果沒來得及執行，則可能會看到以下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cancel 229</span></span>
<span class="line"><span>cancel: cancel-job failed: Job #229 is already completed - can&#39;t cancel.</span></span></code></pre></div><h3 id="雙面打印" tabindex="-1">雙面打印 <a class="header-anchor" href="#雙面打印" aria-label="Permalink to “雙面打印”">​</a></h3><p>要以雙面模式打印，你可以在 <code>lp</code> 命令中使用 <code>sides</code> 選項，該選項不但表示了在紙張的正反面進行打印，還表示了從紙張的哪個邊開始打印。這個設置代表了你期望以雙面縱向文檔的正常方式打印。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp -o sides=two-sided-long-edge Notes.pdf</span></span></code></pre></div><p>如果要所有文檔以雙面模式打印，則可以使用 <code>lpoptions</code> 命令更改 <code>sides</code> 設置以修改 <code>lp</code> 的設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions -o sides=two-sided-short-edge</span></span></code></pre></div><p>要恢復為單面打印，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions -o sides=one-sided</span></span></code></pre></div><h4 id="橫向打印" tabindex="-1">橫向打印 <a class="header-anchor" href="#橫向打印" aria-label="Permalink to “橫向打印”">​</a></h4><p>要以橫向模式打印，可以在 <code>lp</code> 命令中使用 <code>landscape</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp -o landscape penguin.jpg</span></span></code></pre></div><h3 id="cups-unix-通用打印系統" tabindex="-1">CUPS（Unix 通用打印系統） <a class="header-anchor" href="#cups-unix-通用打印系統" aria-label="Permalink to “CUPS（Unix 通用打印系統）”">​</a></h3><p>Linux 系統上使用的打印系統是基於標準的開源打印系統，稱為 <strong>CUPS</strong>，原意是<ruby>Unix 通用打印系統<rt>Common Unix Printing System</rt></ruby>。 它允許計算機充當打印服務器。</p><hr>`,38)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3373502/printing-from-the-linux-command-line.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3373502/printing-from-the-linux-command-line.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/stevenzdg988"},{default:i(()=>[...s[4]||(s[4]=[n("stevenzdg988",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const x=t(c,[["render",h]]);export{y as __pageData,x as default};
